from typing import Optional
from dataclasses import dataclass
from collections import deque

class Helpdesk:
    """A ticket queue for a customer helpdesk."""
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        """Initialize the helpdesk."""
        self.customers = {}
        self.tickets = {}
        self.queue = deque()
        self.ticket_id_counter = 0
        self.closed_tickets = set()

    def add_customer(self, name: str, vip: bool = False) -> None:
        """Add a customer to the helpdesk."""
        self.customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        """Open a ticket; returns its id."""
        if not title:
            raise ValueError("Title cannot be empty")
        if customer not in self.customers:
            raise ValueError("Customer not found")
        if priority not in self.PRIORITIES:
            raise ValueError("Invalid priority")

        self.ticket_id_counter += 1
        ticket_id = self.ticket_id_counter
        self.tickets[ticket_id] = Ticket(customer, title, priority, self.customers[customer])
        self._enqueue_ticket(ticket_id)
        return ticket_id

    def next_ticket(self) -> Optional[int]:
        """Take the ticket that should be handled next out of the queue; None if the queue is empty."""
        if not self.queue:
            return None
        return self.queue.popleft()

    def close(self, ticket_id: int) -> None:
        """Close a ticket."""
        if ticket_id not in self.tickets:
            raise ValueError("Ticket not found")
        self.closed_tickets.add(ticket_id)
        del self.tickets[ticket_id]

    def reopen(self, ticket_id: int) -> None:
        """Put a ticket back into the queue."""
        if ticket_id in self.closed_tickets:
            raise ValueError("Cannot reopen a closed ticket")
        if ticket_id not in self.tickets:
            raise ValueError("Ticket not found")
        self._enqueue_ticket(ticket_id)

    def _enqueue_ticket(self, ticket_id: int) -> None:
        """Enqueue a ticket based on its priority and VIP status."""
        ticket = self.tickets[ticket_id]
        for i, existing_ticket_id in enumerate(self.queue):
            existing_ticket = self.tickets[existing_ticket_id]
            if (ticket.vip and not existing_ticket.vip) or \
               (ticket.vip == existing_ticket.vip and self._compare_priorities(ticket.priority, existing_ticket.priority) < 0) or \
               (ticket.vip == existing_ticket.vip and ticket.priority == existing_ticket.priority and ticket.opened_at < existing_ticket.opened_at):
                self.queue.insert(i, ticket_id)
                return
        self.queue.append(ticket_id)

    def _compare_priorities(self, priority1: str, priority2: str) -> int:
        """Compare two priorities."""
        if priority1 == priority2:
            return 0
        if self.PRIORITIES.index(priority1) < self.PRIORITIES.index(priority2):
            return -1
        return 1


